using Meziantou.Framework.Imaging.Internals;
using Meziantou.Framework.Imaging.Metadata;
using Meziantou.Framework.Imaging.TestHarness.Adapters;
using Meziantou.Framework.Imaging.TestHarness.Fixtures;
using Meziantou.Framework.Imaging.TestHarness.Golden;
using Meziantou.Framework.Imaging.TestHarness.Heif;
using Meziantou.Framework.Imaging.TestHarness.Pixels;

namespace Meziantou.Framework.Imaging.Tests.Conformance;

/// <summary>
/// HEIC decoding (still images and image sequences) against the corpus generated by
/// <c>tools/Meziantou.Framework.Imaging.CorpusGenerator/HeicCorpus.Container.cs</c>. The eager, sequential and identify suites
/// already compare every fixture under its policy; these tests compare what the library reports with the structure that the
/// independent reader (<see cref="ReferenceHeif"/>) finds in the bytes, check that the fixtures cover the container features,
/// that the samples no matrix applies to are exact, and pin the policy of each matrixed fixture to the measurement: one unit
/// and the measured mean error + 0.01 against the exact-rational reference (<c>LibraryHeicMeasurements</c> in the generator),
/// so that a numerical change of the color conversion is noticed and reviewed.
/// </summary>
public sealed class HeicDecoderConformanceTests
{
    public static TheoryData<string> ValidFixtures => [.. Valid.Select(fixture => fixture.Id)];

    public static TheoryData<string> ExactFixtures => [.. Valid.Where(fixture => fixture.Policy.IsExact).Select(fixture => fixture.Id)];

    public static TheoryData<string> ToleranceFixtures => [.. Valid.Where(fixture => !fixture.Policy.IsExact).Select(fixture => fixture.Id)];

    public static TheoryData<string> SequenceFixtures => [.. Valid.Where(fixture => fixture.Entry.HasFeature("heic.sequence")).Select(fixture => fixture.Id)];

    private static IEnumerable<GoldenFixture> Valid => GoldenCorpus.Default.GetIds(format: "heic", kind: FixtureKinds.Valid).Select(id => GoldenCorpus.Default.Get(id));

    private static bool IsMatrixed(GoldenFixture fixture) => (fixture.Entry.Features ?? []).Any(feature => feature.StartsWith("heic.matrix=", StringComparison.Ordinal) && feature != "heic.matrix=0");

    [Fact]
    public void FixturesCoverTheDecoderFeatures()
    {
        var fixtures = Valid.ToList();
        var features = fixtures.SelectMany(fixture => fixture.Entry.Features ?? []).SelectMany(Expand).ToHashSet(StringComparer.Ordinal);
        foreach (var feature in new[]
        {
            "heic.majorBrand=heic", "heic.majorBrand=heix", "heic.majorBrand=hevc", "heic.majorBrand=hevx", "heic.majorBrand=mif1", "heic.majorBrand=miaf", "heic.majorBrand=msf1", "heic.brands=avif",
            "heic.bitDepth=8", "heic.bitDepth=10", "heic.bitDepth=12",
            "heic.subsampling=4:4:4", "heic.subsampling=4:2:2", "heic.subsampling=4:2:0", "heic.subsampling=4:0:0",
            "heic.matrix=0", "heic.matrix=1", "heic.matrix=2", "heic.matrix=5", "heic.matrix=6", "heic.matrix=8", "heic.matrix=9", "heic.range=full", "heic.range=limited",
            "heic.colr=nclx", "heic.colr=icc", "heic.colr=none", "heic.videoSignal=none", "heic.videoSignal=range", "heic.videoSignal=colour",
            "heic.chromaLoc=default", "heic.chromaLoc=0", "heic.chromaLoc=1", "heic.chromaLoc=2",
            "heic.lossless", "heic.conformanceWindow", "heic.alpha", "heic.alpha.urn=hevc", "heic.alpha.urn=mpegB", "heic.alpha.subsampling=4:0:0", "heic.alpha.subsampling=4:2:0", "heic.alpha.range=limited",
            "heic.grid=2x2", "heic.grid=2x1", "heic.grid=3x2", "heic.clap", "heic.irot=1", "heic.irot=2", "heic.irot=3", "heic.imir=0", "heic.imir=1",
            "heic.metadata=exif", "heic.metadata=xmp", "heic.thumbnail", "heic.auxiliary=other",
            "heic.hvcc.lengthSize=1", "heic.hvcc.lengthSize=2", "heic.hvcc.lengthSize=4", "heic.hvcc.incompleteArrays", "heic.hvcc.severalParameterSets", "heic.parameterSets=in-band",
            "heic.layout=media-first", "heic.idat", "heic.extents=3", "heic.boxes=free", "heic.boxes=unknown", "heic.boxes=large-size", "heic.boxes=to-end", "heic.trailingData",
            "heic.sequence", "heic.seq.sampleEntry=hvc1", "heic.seq.sampleEntry=hev1", "heic.seq.interFrames", "heic.seq.compositionOffsets", "heic.seq.reordered", "heic.seq.editMediaTime",
            "heic.seq.editList=none", "heic.seq.editList=once", "heic.seq.editList=repeat", "heic.seq.editList=repeat-indefinite",
            "heic.seq.sampleSizes=stsz", "heic.seq.sampleSizes=stz2", "heic.seq.chunkOffsets=stco", "heic.seq.chunkOffsets=co64",
            "heic.seq.metadataSource=track", "heic.seq.metadataSource=file", "heic.seq.metadataAfterSamples", "heic.seq.fileImageNotRead", "heic.seq.samplesOutOfOrder",
        })
        {
            Assert.Contains(feature, features);
        }

        // Every sample format of the color images at every bit depth the decoder reads, an alpha plane at each depth, and
        // every chroma sample location of a 4:2:0 picture at 8 and at more than 8 bits
        foreach (var subsampling in new[] { "4:4:4", "4:2:2", "4:2:0", "4:0:0" })
        {
            foreach (var depth in new[] { 8, 10, 12 })
            {
                Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("heic.subsampling=" + subsampling) && fixture.Entry.HasFeature(string.Create(CultureInfo.InvariantCulture, $"heic.bitDepth={depth}")));
            }
        }

        foreach (var depth in new[] { 8, 10, 12 })
        {
            Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("heic.alpha") && fixture.Entry.HasFeature(string.Create(CultureInfo.InvariantCulture, $"heic.bitDepth={depth}")));
        }

        foreach (var location in new[] { "default", "1", "2" })
        {
            Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("heic.chromaLoc=" + location) && fixture.Entry.HasFeature("heic.bitDepth=8"));
            Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("heic.chromaLoc=" + location) && !fixture.Entry.HasFeature("heic.bitDepth=8"));
        }

        // Both ways a picture is smaller than what is coded: a conformance window of the bitstream, a clap property of the
        // file, and both; and a grid under each
        Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("heic.conformanceWindow") && fixture.Entry.HasFeature("heic.clap"));
        Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("heic.conformanceWindow") && fixture.Entry.HasFeature("heic.sequence"));
        Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("heic.grid=2x2") && fixture.Entry.HasFeature("heic.irot=3") && fixture.Entry.HasFeature("heic.thumbnail"));
        Assert.Contains(fixtures, fixture => fixture.Entry.HasFeature("heic.grid=2x1") && fixture.Entry.HasFeature("heic.alpha"));

        // Files written by an encoder and files assembled box by box
        Assert.Contains(fixtures, fixture => fixture.Entry.Provenance.Origin == "generated" && (fixture.Entry.Provenance.Tools ?? []).Any(tool => tool.Contains("heif-enc", StringComparison.Ordinal)));
        Assert.Contains(fixtures, fixture => fixture.Entry.Provenance.Origin == "hand-authored");

        static IEnumerable<string> Expand(string feature)
        {
            var separator = feature.IndexOf('=', StringComparison.Ordinal);
            return separator < 0 ? [feature] : feature[(separator + 1)..].Split(',').Select(value => feature[..(separator + 1)] + value);
        }
    }

    [Theory]
    [MemberData(nameof(ValidFixtures))]
    public void DecodedImageHasTheStructureOfTheFile(string id)
    {
        // The independent reader gives the structure; the manifest must say the same, and so must the library
        var fixture = GoldenCorpus.Default.Get(id);
        var data = fixture.ReadInput();
        var file = ReferenceHeif.Parse(data);
        var expected = fixture.Expected;
        using var image = Image.Load(data);
        var info = Image.Identify(data, new ImageIdentifyOptions { Mode = ImageIdentifyMode.FullScan });

        ReferenceHeif.HevcConfiguration configuration;
        ReferenceHeif.ColorDescription? nclx;
        ReadOnlyMemory<byte>? icc;
        bool hasAlpha;
        int alphaBitDepth;
        (int Width, int Height) size;
        var orientation = 1;
        if (file.IsSequence)
        {
            var track = file.ColorTrack;
            Assert.NotNull(track);
            configuration = track.HevcConfiguration!;
            nclx = track.Nclx;
            icc = track.IccProfile;
            hasAlpha = file.AlphaTrack is not null;
            alphaBitDepth = file.AlphaTrack?.HevcConfiguration?.BitDepthLuma ?? 0;
            size = (track.Width, track.Height);
            if (track.CleanAperture is { } trackAperture)
            {
                var rectangle = trackAperture.GetRectangle(size.Width, size.Height);
                Assert.NotNull(rectangle);
                size = (rectangle.Value.Width, rectangle.Value.Height);
                Assert.Equal(trackAperture, file.AlphaTrack?.CleanAperture ?? trackAperture);
            }

            Assert.Equal(track.CleanAperture is not null, fixture.Entry.HasFeature("heic.clap"));
            Assert.Equal(track.SampleEntryType, fixture.Entry.Features!.Single(feature => feature.StartsWith("heic.seq.sampleEntry=", StringComparison.Ordinal))["heic.seq.sampleEntry=".Length..]);

            // One image per sample, in the order of the composition times, each one until the next one is presented; the
            // plays of the edit list
            var order = track.PresentationOrder;
            Assert.Equal(track.Samples.Count, expected.FrameCount);
            Assert.Equal(track.Samples.Count, image.Frames.Count);
            Assert.Equal(track.Samples.Count, info.FrameCount);
            for (var i = 0; i < order.Count; i++)
            {
                var duration = new FrameDuration(checked((uint)order[i].Duration), track.Timescale);
                Assert.Equal(duration, image.Frames[i].Metadata.Duration);
                Assert.Equal(RationalDuration.Create(duration.Numerator, duration.Denominator), fixture.GetDuration(i));
            }

            Assert.Equal(!order.Select(entry => entry.SampleIndex).SequenceEqual(Enumerable.Range(0, order.Count)), fixture.Entry.HasFeature("heic.seq.reordered"));
            Assert.Equal(track.Samples.Count > 1, image.Animation is not null);
            if (track.Samples.Count > 1)
            {
                Assert.Equal(track.TotalPlays, expected.Animation!.TotalPlays);
                Assert.Equal(track.TotalPlays, image.Animation!.TotalPlays);
                Assert.Equal(track.TotalPlays, info.Animation!.TotalPlays);
            }

            if (file.AlphaTrack is { } alphaTrack)
            {
                Assert.Equal(track.Samples.Count, alphaTrack.Samples.Count);
                Assert.Equal((track.Width, track.Height), (alphaTrack.Width, alphaTrack.Height));
            }

            // The Exif and XMP items of a sequence: those of the meta box of its track, or else of the meta box of the
            // file when it precedes the moov box. A header identification does not read them
            var (exif, xmp) = file.FindSequenceMetadata();
            var expectedExif = exif is null ? null : Convert.ToHexString(file.ReadExifPayload(exif));
            var expectedXmp = xmp is null ? null : Convert.ToHexString(file.ReadItemData(xmp));
            Assert.Equal(expectedExif, image.Metadata.ExifProfile is { } exifProfile ? Convert.ToHexString(exifProfile.Data.Span) : null);
            Assert.Equal(expectedXmp, image.Metadata.XmpProfile is { } xmpProfile ? Convert.ToHexString(xmpProfile.Data.Span) : null);
            Assert.Equal(expectedExif, info.Metadata.ExifProfile is { } scannedExif ? Convert.ToHexString(scannedExif.Data.Span) : null);
            Assert.Equal(expectedXmp, info.Metadata.XmpProfile is { } scannedXmp ? Convert.ToHexString(scannedXmp.Data.Span) : null);
            Assert.Equal(exif is not null, expected.Profiles.Exif is not null);
            Assert.Equal(xmp is not null, expected.Profiles.Xmp is not null);
            var header = Image.Identify(data);
            Assert.Null(header.Metadata.ExifProfile);
            Assert.Null(header.Metadata.XmpProfile);
            Assert.Equal(track.Samples.Count, header.FrameCount);
        }
        else
        {
            var primary = file.PrimaryItem;
            Assert.NotNull(primary);
            var coded = primary;
            if (primary.Type == "grid")
            {
                var (rows, columns, width, height) = file.ReadGridDescriptor(primary);
                var tiles = file.GetGridTiles(primary);
                Assert.Equal(rows * columns, tiles.Count);
                Assert.Equal(primary.Size, (width, height));
                Assert.True(fixture.Entry.HasFeature(string.Create(CultureInfo.InvariantCulture, $"heic.grid={columns}x{rows}")));
                Assert.All(tiles, tile => Assert.Equal("hvc1", tile.Type));
                coded = tiles[0];
            }

            Assert.Equal("hvc1", coded.Type);
            configuration = coded.HevcConfiguration!;
            nclx = primary.Nclx;
            icc = primary.IccProfile;
            hasAlpha = file.AlphaItem is not null;
            alphaBitDepth = file.AlphaItem is { } alpha ? (alpha.Type == "grid" ? file.GetGridTiles(alpha)[0] : alpha).HevcConfiguration!.BitDepthLuma : 0;
            var ispe = primary.Size!.Value;
            size = ((int)ispe.Width, (int)ispe.Height);
            if (primary.CleanAperture is { } aperture)
            {
                var rectangle = aperture.GetRectangle(size.Width, size.Height);
                Assert.NotNull(rectangle);
                size = (rectangle.Value.Width, rectangle.Value.Height);
            }

            Assert.Equal(primary.CleanAperture is not null, fixture.Entry.HasFeature("heic.clap"));
            orientation = primary.Orientation;
            Assert.Single(image.Frames);
            Assert.Null(image.Animation);
            Assert.Equal(FrameDuration.Zero, image.Frames[0].Metadata.Duration);

            var descriptions = file.FindDescriptions(primary.Id);
            var exif = descriptions.FirstOrDefault(item => item.Type == "Exif");
            var xmp = descriptions.FirstOrDefault(item => item.ContentType == "application/rdf+xml");
            Assert.Equal(exif is null ? null : Convert.ToHexString(file.ReadExifPayload(exif)), image.Metadata.ExifProfile is { } stillExif ? Convert.ToHexString(stillExif.Data.Span) : null);
            Assert.Equal(xmp is null ? null : Convert.ToHexString(file.ReadItemData(xmp)), image.Metadata.XmpProfile is { } stillXmp ? Convert.ToHexString(stillXmp.Data.Span) : null);
        }

        // Size (the clean aperture is applied, the orientation is not), orientation, pixel format, bit depth
        Assert.Equal(size, (expected.Width, expected.Height));
        Assert.Equal(size, (image.Width, image.Height));
        Assert.Equal(size, (info.Width, info.Height));
        Assert.Equal(orientation, expected.Orientation);
        Assert.Equal((ExifOrientation)orientation, image.Metadata.Orientation);
        Assert.Equal((ExifOrientation)orientation, info.Metadata.Orientation);
        var deep = Math.Max(configuration.BitDepthLuma, alphaBitDepth) > 8;
        var pixelFormat = (configuration.IsMonochrome, hasAlpha, deep) switch
        {
            (true, false, false) => PixelFormat.Gray8,
            (true, false, true) => PixelFormat.Gray16,
            (true, true, false) => PixelFormat.La16,
            (true, true, true) => PixelFormat.La32,
            (false, false, false) => PixelFormat.Rgb24,
            (false, false, true) => PixelFormat.Rgb48,
            (false, true, false) => PixelFormat.Rgba32,
            (false, true, true) => PixelFormat.Rgba64,
        };
        Assert.Equal(pixelFormat.ToString(), expected.PixelFormat);
        Assert.Equal(pixelFormat, image.PixelFormat);
        Assert.Equal(pixelFormat, info.PixelFormat);
        Assert.Equal(configuration.BitDepthLuma, expected.BitsPerComponent);
        Assert.Equal(configuration.BitDepthLuma, info.BitsPerComponent);
        Assert.Equal(hasAlpha, info.MayHaveTransparency);
        Assert.Equal(hasAlpha, fixture.Entry.HasFeature("heic.alpha"));
        Assert.Equal(ImageFormat.Heic, image.Metadata.SourceFormat);
        Assert.Equal(ImageFormat.Heic, info.Format);

        // The file type box is all a detection reads: a file that also declares the brands of AVIF is only known to be an
        // HEIC file once the codec of its primary item, or of its track, is known
        Assert.Equal(fixture.Entry.HasFeature("heic.brands=avif") ? ImageFormat.Avif : ImageFormat.Heic, Image.DetectFormat(data));

        // The sample format of the record is the one the features record
        var subsampling = configuration.ChromaFormat switch { 0 => "4:0:0", 1 => "4:2:0", 2 => "4:2:2", _ => "4:4:4" };
        Assert.True(fixture.Entry.HasFeature("heic.subsampling=" + subsampling));
        Assert.True(fixture.Entry.HasFeature(string.Create(CultureInfo.InvariantCulture, $"heic.bitDepth={configuration.BitDepthLuma}")));

        // A colr box of type nclx is the color description; otherwise the manifest holds the one of the bitstream
        if (nclx is not null)
        {
            Assert.Equal(new CicpColorDescription((byte)nclx.ColorPrimaries, (byte)nclx.TransferCharacteristics, (byte)nclx.MatrixCoefficients, nclx.FullRange), image.Metadata.Cicp);
        }

        var expectedCicp = expected.Cicp is { } cicp ? new CicpColorDescription((byte)cicp.ColorPrimaries, (byte)cicp.TransferCharacteristics, (byte)cicp.MatrixCoefficients, cicp.FullRange) : null;
        Assert.Equal(expectedCicp, image.Metadata.Cicp);
        Assert.Equal(expectedCicp, info.Metadata.Cicp);
        Assert.Equal(icc is null ? null : Convert.ToHexString(icc.Value.Span), image.Metadata.IccProfile is { } profile ? Convert.ToHexString(profile.Data.Span) : null);

        // Color profiles and color descriptions are labels: neither changes the transfer function label
        Assert.Equal(ColorTransferFunction.Srgb, image.Metadata.TransferFunction);
    }

    [Theory]
    [MemberData(nameof(ExactFixtures))]
    public void ExactFixturesAreExact(string id)
    {
        // Identity-matrix, monochrome and alpha samples are scaled without matrix: no tolerance, low bits included. A
        // matrixed fixture is only compared exactly when every independent decoder agrees exactly with the reference
        var fixture = GoldenCorpus.Default.Get(id);
        if (IsMatrixed(fixture))
        {
            var checks = fixture.Entry.Reference?.CrossChecks?.Where(check => check.MaxAbsoluteError is not null).ToList() ?? [];
            Assert.All(checks, check => Assert.Equal(0, check.MaxAbsoluteError));
        }

        using var image = Image.Load(fixture.ReadInput());
        var snapshot = ImageSnapshots.Capture(image);
        Assert.Equal(fixture.Expected.FrameCount, snapshot.Frames.Count);
        for (var i = 0; i < snapshot.Frames.Count; i++)
        {
            var actual = snapshot.Frames[i].Pixels;
            Assert.True(fixture.GetFrame(i, actual.Layout).Span.SequenceEqual(actual.Span), $"{id} frame {i} differs from the reference.");
        }
    }

    [Theory]
    [MemberData(nameof(ToleranceFixtures))]
    public void ToleranceIsTheMeasuredDisagreementWithTheReference(string id)
    {
        var fixture = GoldenCorpus.Default.Get(id);
        Assert.True(IsMatrixed(fixture), $"'{id}' has a tolerance and no matrix applies to its samples.");
        using var image = Image.Load(fixture.ReadInput());
        var snapshot = ImageSnapshots.Capture(image);
        Assert.Equal(fixture.Expected.FrameCount, snapshot.Frames.Count);
        var max = 0;
        var sum = 0.0;
        var location = "(none)";
        for (var i = 0; i < snapshot.Frames.Count; i++)
        {
            var actual = snapshot.Frames[i].Pixels;
            var (frameMax, frameMean, frameLocation) = Measure(fixture.GetFrame(i, actual.Layout), actual);
            sum += frameMean;
            if (frameMax > max)
            {
                max = frameMax;
                location = string.Create(CultureInfo.InvariantCulture, $"frame {i} {frameLocation}");
            }
        }

        // Errors on the 8-bit scale: a unit of a 16-bit sample is 1/257
        var scale = snapshot.Frames[0].Pixels.Layout.ScaleFrom8Bit;
        var mean = Math.Round(sum / snapshot.Frames.Count / scale, 4, MidpointRounding.AwayFromZero);
        var units = (max + scale - 1) / scale;
        TestContext.Current.TestOutputHelper?.WriteLine(string.Create(CultureInfo.InvariantCulture, $"[\"{id}\"] = ({units}, {mean:0.0###}), // max {max} at {location}"));

        // The HEVC planes are exact; only the rounding of the matrix coefficients differs from the exact conversion
        Assert.True(units <= 1, string.Create(CultureInfo.InvariantCulture, $"'{id}' differs from the exact conversion by {max} at {location}: more than one unit."));

        var policy = fixture.Policy;
        var checks = fixture.Entry.Reference?.CrossChecks?.Where(check => check.ExcludedFromTolerance != true && check.MaxAbsoluteError is not null).ToList() ?? [];
        Assert.NotEmpty(checks);
        var (justifiedMax, justifiedMean) = ComparisonPolicy.GetMaximumJustifiedTolerance(checks.Max(check => check.MaxAbsoluteError!.Value), checks.Max(check => check.MeanAbsoluteError!.Value));
        var expectedMax = Math.Min(justifiedMax, 1);
        var expectedMean = Math.Min(justifiedMean, Math.Ceiling(Math.Round((mean + 0.01) * 100, 6, MidpointRounding.AwayFromZero)) / 100);
        Assert.True(policy.MaxAbsoluteError == expectedMax && Math.Abs(policy.MaxMeanAbsoluteError - expectedMean) < 1e-9,
            string.Create(CultureInfo.InvariantCulture, $"The policy of '{id}' (max {policy.MaxAbsoluteError}, mean {policy.MaxMeanAbsoluteError}) is not the one derived from the measured disagreement (max {units}, mean {mean}: max {expectedMax}, mean {expectedMean}). Update LibraryHeicMeasurements in tools/Meziantou.Framework.Imaging.CorpusGenerator/HeicCorpus.Container.cs after reviewing the change."));
    }

    public static TheoryData<string> FixturesWithoutColorDescriptionBox => [.. Valid.Where(fixture => !(fixture.Entry.Features ?? []).Any(feature => feature.StartsWith("heic.colr=", StringComparison.Ordinal) && feature.Split('=')[1].Split(',').Contains("nclx", StringComparer.Ordinal))).Select(fixture => fixture.Id)];

    [Theory]
    [MemberData(nameof(FixturesWithoutColorDescriptionBox))]
    public void HeaderIdentificationReadsTheSequenceParameterSetOfAFileWithoutColorDescriptionBox(string id)
    {
        // Without colr box of type nclx the bitstream describes the colors: its sequence parameter set, which the
        // configuration record holds, so that a header identification reports the color model and the color description
        // of a full scan and of a load wherever the coded data are. When the parameter sets are in the coded data only, it
        // reads on to them; had they gone by before the box that describes the image, the color model would be unknown
        var fixture = GoldenCorpus.Default.Get(id);
        var data = fixture.ReadInput();
        var file = ReferenceHeif.Parse(data);
        Assert.Null(file.IsSequence ? file.ColorTrack!.Nclx : file.PrimaryItem!.Nclx);
        var expected = fixture.Expected;
        var expectedCicp = expected.Cicp is { } cicp ? new CicpColorDescription((byte)cicp.ColorPrimaries, (byte)cicp.TransferCharacteristics, (byte)cicp.MatrixCoefficients, cicp.FullRange) : null;
        var full = Image.Identify(data, new ImageIdentifyOptions { Mode = ImageIdentifyMode.FullScan });
        Assert.Equal(Enum.Parse<ImageColorModel>(expected.ColorModel!), full.ColorModel);
        Assert.Equal(expectedCicp, full.Metadata.Cicp);

        var stream = new MemoryStream(data);
        var header = Image.Identify(stream);
        Assert.Equal(ImageIdentifyMode.Header, header.IdentifyMode);
        Assert.Equal((expected.Width, expected.Height), (header.Width, header.Height));
        Assert.Equal(Enum.Parse<PixelFormat>(expected.PixelFormat), header.PixelFormat);
        Assert.False(FixtureTraits.HeaderCannotTellTheColorModel(fixture));
        Assert.Equal(full.ColorModel, header.ColorModel);
        Assert.Equal(expectedCicp, header.Metadata.Cicp);
    }

    [Theory]
    [MemberData(nameof(SequenceFixtures))]
    public void ReaderReturnsTheImagesOfASequenceInPresentationOrder(string id)
    {
        // The samples are in decoding order; a sequential reader returns the images in the order of their composition
        // times, each with its duration, and reports the plays before the first one
        var fixture = GoldenCorpus.Default.Get(id);
        var data = fixture.ReadInput();
        var track = ReferenceHeif.Parse(data).ColorTrack!;
        var order = track.PresentationOrder;
        using var stream = InputVariants.CreateStream(InputVariant.NonSeekableStream, data);
        if (fixture.Expected.PixelFormat is "Rgba64" or "Gray16" or "Rgb48" or "La32")
        {
            using var reader = Image.OpenReader<Rgba64>(stream);
            Read(reader);
        }
        else
        {
            using var reader = Image.OpenReader<Rgba32>(stream);
            Read(reader);
        }

        void Read<TPixel>(ImageReader<TPixel> reader)
            where TPixel : unmanaged
        {
            Assert.Equal(ImageFormat.Heic, reader.Info.Format);
            Assert.Equal(order.Count, reader.Info.FrameCount);
            Assert.Equal(order.Count > 1 ? track.TotalPlays : null, reader.Info.Animation?.TotalPlays);
            Assert.Equal(order.Count > 1, reader.Info.Animation is not null);
            var index = 0;
            while (reader.ReadFrame() is { } image)
            {
                using (image)
                {
                    // The image of the presentation slot, under the policy of the fixture
                    Assert.Equal(new FrameDuration(checked((uint)order[index].Duration), track.Timescale), image.Frames[0].Metadata.Duration);
                    GoldenAssert.FrameMatches(fixture, index, ImageSnapshots.Capture(image).Frames[0].Pixels);
                }

                index++;
            }

            Assert.Equal(order.Count, index);
        }
    }

    [Fact]
    public void ExifOrientationTagIsIgnored()
    {
        // The Exif payload says "rotate 90 degrees" (6); the irot property of the item is a half turn (3)
        var fixture = GoldenCorpus.Default.Get("heic/metadata-exif-xmp-icc");
        using var image = Image.Load(fixture.ReadInput());
        Assert.Equal(ExifOrientation.RightTop, ExifTiff.ReadOrientation(image.Metadata.ExifProfile!.Data.Span));
        Assert.Equal(ExifOrientation.BottomRight, image.Metadata.Orientation);
        Assert.Equal(3, ReferenceHeif.Parse(fixture.ReadInput()).PrimaryItem!.Orientation);
        Assert.Equal((fixture.Expected.Width, fixture.Expected.Height), (image.Width, image.Height)); // reported, never applied
    }

    [Fact]
    public void ColorBoxDescribesTheColorsBeforeTheBitstream()
    {
        // Two containers around the same HEVC payload, whose sequence parameter set says BT.709 limited range
        var bare = GoldenCorpus.Default.Get("heic/no-colr-bitstream-bt709-limited");
        var overridden = GoldenCorpus.Default.Get("heic/nclx-overrides-bitstream");
        Assert.Equal(ReadPrimaryPayload(bare), ReadPrimaryPayload(overridden));

        using var first = Image.Load(bare.ReadInput());
        using var second = Image.Load(overridden.ReadInput());
        Assert.Equal(new CicpColorDescription(1, 1, 1, fullRange: false), first.Metadata.Cicp);
        Assert.Equal(new CicpColorDescription(1, 13, 6, fullRange: true), second.Metadata.Cicp);
        Assert.NotEqual(bare.Expected.Frames[0].Buffers[0].Sha256, overridden.Expected.Frames[0].Buffers[0].Sha256);
        Assert.NotEqual(ImageSnapshots.Capture(first).Frames[0].Pixels.ToArray(), ImageSnapshots.Capture(second).Frames[0].Pixels.ToArray());

        // What heif-enc writes has the same description in both places: without its colr box, the same pixels
        var encoded = GoldenCorpus.Default.Get("heic/lossy-444-bt709-limited");
        var stripped = GoldenCorpus.Default.Get("heic/no-colr-bitstream-bt709");
        Assert.Equal(ReadPrimaryPayload(encoded), ReadPrimaryPayload(stripped));
        Assert.Equal(encoded.Expected.Frames[0].Buffers[0].Sha256, stripped.Expected.Frames[0].Buffers[0].Sha256);

        static string ReadPrimaryPayload(GoldenFixture fixture)
        {
            var file = ReferenceHeif.Parse(fixture.ReadInput());
            return Convert.ToHexString(file.ReadItemData(file.PrimaryItem!));
        }
    }

    [Fact]
    public void FileWithoutVideoSignalDescriptionUsesTheLimitedRange()
    {
        // Neither a colr box nor a video signal description in the sequence parameter set: video_full_range_flag is
        // inferred to be 0 (Rec. ITU-T H.265, clause E.3.1), so the samples use the limited range, and unspecified matrix
        // coefficients convert as BT.601; there is no color description to report. The same holds for a monochrome image
        var fixture = GoldenCorpus.Default.Get("heic/no-colr-no-signal-444");
        Assert.True(fixture.Entry.HasFeature("heic.videoSignal=none") && fixture.Entry.HasFeature("heic.range=limited") && fixture.Entry.HasFeature("heic.matrix=2"));
        Assert.Null(fixture.Expected.Cicp);
        using var image = Image.Load(fixture.ReadInput());
        Assert.Null(image.Metadata.Cicp);
        Assert.Equal(ImageColorModel.YCbCr, Image.Identify(fixture.ReadInput()).ColorModel);

        // A video signal description that says "limited range" is the same conversion: the fixture that has one has the
        // same payload settings, and no color description either
        var limited = GoldenCorpus.Default.Get("heic/no-colr-bitstream-limited-range");
        Assert.True(limited.Entry.HasFeature("heic.videoSignal=range") && limited.Entry.HasFeature("heic.range=limited"));
        Assert.Null(limited.Expected.Cicp);
        var gray = GoldenCorpus.Default.Get("heic/window-gray8-lossless");
        Assert.True(gray.Entry.HasFeature("heic.videoSignal=none") && gray.Entry.HasFeature("heic.range=limited") && gray.Entry.HasFeature("heic.subsampling=4:0:0"));

        // No fixture without colr box and without video signal description is read as full range
        Assert.DoesNotContain(Valid, candidate => candidate.Entry.HasFeature("heic.colr=none") && candidate.Entry.HasFeature("heic.videoSignal=none") && candidate.Entry.HasFeature("heic.range=full"));
    }

    [Fact]
    public void AlphaPlaneWithoutVideoSignalDescriptionUsesTheFullRange()
    {
        // The exception to the rule above: an alpha plane is not video. Its samples use the full range unless its
        // bitstream explicitly says limited
        foreach (var id in new[] { "heic/alpha-420-picture", "heic/alpha-mpegb-urn" })
        {
            var fixture = GoldenCorpus.Default.Get(id);
            var file = ReferenceHeif.Parse(fixture.ReadInput());
            Assert.Null(file.PrimaryItem!.Nclx);
            Assert.True(fixture.Entry.HasFeature("heic.videoSignal=none") && fixture.Entry.HasFeature("heic.range=limited") && !fixture.Entry.HasFeature("heic.alpha.range=limited"), id);

            // The alpha ramp of the source goes from 0 to 255: full-range samples reach both ends
            var alpha = fixture.GetFrame(0, RawPixelLayout.Rgba8);
            var values = Enumerable.Range(0, alpha.Width * alpha.Height).Select(i => alpha.GetSample(i % alpha.Width, i / alpha.Width, 3)).ToList();
            Assert.True(values.Min() <= 2 && values.Max() >= 253, id);
        }

        Assert.True(GoldenCorpus.Default.Get("heic/alpha-limited-range").Entry.HasFeature("heic.alpha.range=limited"));
    }

    [Fact]
    public void LayoutsOfOnePayloadPresentTheSamePixels()
    {
        // The assembled layouts hold the items of heic/lossless-rgb8: same references, whatever the boxes around them
        var source = GoldenCorpus.Default.Get("heic/lossless-rgb8");
        var layouts = Valid.Where(fixture => fixture.Id.StartsWith("heic/layout-", StringComparison.Ordinal) || fixture.Id.StartsWith("heic/brand", StringComparison.Ordinal)).ToList();
        Assert.HasCountGreaterThanOrEqual(7, layouts);
        Assert.All(layouts, fixture => Assert.Equal(source.Expected.Frames[0].Buffers.Select(buffer => buffer.Sha256), fixture.Expected.Frames[0].Buffers.Select(buffer => buffer.Sha256)));

        // One payload under every size of NAL unit length and every place of its parameter sets
        var plain = GoldenCorpus.Default.Get("heic/no-colr-no-signal-444");
        foreach (var id in new[] { "heic/hvcc-length-size-1", "heic/hvcc-length-size-2", "heic/hvcc-several-parameter-sets", "heic/hvcc-incomplete-arrays", "heic/parameter-sets-in-band" })
        {
            Assert.Equal(plain.Expected.Frames[0].Buffers.Select(buffer => buffer.Sha256), GoldenCorpus.Default.Get(id).Expected.Frames[0].Buffers.Select(buffer => buffer.Sha256));
        }

        var sequence = GoldenCorpus.Default.Get("heic/sequence-window-rgb");
        foreach (var id in new[] { "heic/sequence-mdat-first", "heic/sequence-co64-stz2", "heic/sequence-msf1-major", "heic/sequence-brands-avis-and-hevc", "heic/sequence-file-meta-after-samples", "heic/sequence-track-meta-idat" })
        {
            var fixture = GoldenCorpus.Default.Get(id);
            Assert.Equal(sequence.Expected.Frames.Select(frame => (frame.Duration, frame.Buffers[0].Sha256)), fixture.Expected.Frames.Select(frame => (frame.Duration, frame.Buffers[0].Sha256)));
        }

        // The same stream with B pictures under an hvc1 and an hev1 sample entry, with and without edit list
        var reordered = GoldenCorpus.Default.Get("heic/sequence-window-reordered-2-plays");
        foreach (var id in new[] { "heic/sequence-hev1-in-band", "heic/sequence-no-edit-list-reordered", "heic/sequence-length-size-2" })
        {
            var fixture = GoldenCorpus.Default.Get(id);
            Assert.Equal(reordered.Expected.Frames.Select(frame => (frame.Duration, frame.Buffers[0].Sha256)), fixture.Expected.Frames.Select(frame => (frame.Duration, frame.Buffers[0].Sha256)));
        }
    }

    [Fact]
    public void ReaderGivesMetadataThatFollowTheSamplesWithTheLastImageAtTheLatest()
    {
        // One byte per read: the first images are returned before the item data, which follow the samples, are read
        var fixture = GoldenCorpus.Default.Get("heic/sequence-file-meta-after-samples");
        var data = fixture.ReadInput();
        var file = ReferenceHeif.Parse(data);
        var (exif, xmp) = file.FindSequenceMetadata();
        Assert.True(exif!.Extents[0].Offset > file.ColorTrack!.Samples[^1].Offset && xmp!.Extents[0].Offset > file.ColorTrack.Samples[^1].Offset);
        using var stream = InputVariants.CreateStream(InputVariant.ShortReadStream, data);
        using var reader = Image.OpenReader<Rgb24>(stream);
        Assert.Null(reader.Info.Metadata.ExifProfile);
        var images = new List<Image<Rgb24>>();
        try
        {
            while (reader.ReadFrame() is { } image)
            {
                images.Add(image);
            }

            Assert.HasCount(fixture.Expected.FrameCount, images);
            Assert.True(fixture.Expected.Profiles.Exif!.Matches(images[^1].Metadata.ExifProfile!.Data.Span));
            Assert.True(fixture.Expected.Profiles.Xmp!.Matches(images[^1].Metadata.XmpProfile!.Data.Span));
        }
        finally
        {
            foreach (var image in images)
            {
                image.Dispose();
            }
        }
    }

    [Fact]
    public void ConformanceWindowThatRemovesThePaddingDoesNotCountTowardTheCanvasLimits()
    {
        // A 20x17 image in a 24x24 picture: the window removes 4 columns and 7 rows, less than a minimum coding block (8),
        // the padding every coded picture may need. The limits of the image accept it, identified or decoded
        var fixture = GoldenCorpus.Default.Get("heic/window-rgb8-lossless");
        Assert.True(fixture.Entry.HasFeature("heic.conformanceWindow"));
        Assert.DoesNotContain(fixture.Entry.Features!, feature => feature.StartsWith("heic.checkedSize=", StringComparison.Ordinal));
        var data = fixture.ReadInput();
        var limits = new ImageConfiguration { Limits = new ImageResourceLimits { MaxWidth = 20, MaxHeight = 17, MaxFramePixels = 340 } };
        var info = Image.Identify(data, new ImageIdentifyOptions { Mode = ImageIdentifyMode.FullScan, Configuration = limits });
        Assert.Equal((20, 17), (info.Width, info.Height));
        using (var image = Image.Load(data, new ImageDecodeOptions { Configuration = limits }))
        {
            Assert.Equal((20, 17), (image.Width, image.Height));
        }

        var exception = Assert.Throws<ImageResourceLimitException>(() => Image.Load(data, new ImageDecodeOptions { Configuration = new ImageConfiguration { Limits = new ImageResourceLimits { MaxWidth = 19 } } }));
        Assert.Equal((ImageResourceLimitKind.Width, 20L), (exception.Kind, exception.Requested));
    }

    [Fact]
    public void ConformanceWindowThatRemovesMoreThanThePaddingCountsTheWholePicture()
    {
        // A 20x18 image that is the corner of a 32x32 picture: the window removes 12 columns and 14 rows, which are decoded
        // all the same. An identification reads the size the file declares; a load needs limits that hold the picture
        var fixture = GoldenCorpus.Default.Get("heic/window-beyond-padding-444");
        Assert.True(fixture.Entry.HasFeature("heic.checkedSize=32x32"));
        Assert.Equal((20, 18), (fixture.Expected.Width, fixture.Expected.Height));
        var data = fixture.ReadInput();
        var limits = new ImageConfiguration { Limits = new ImageResourceLimits { MaxWidth = 20, MaxHeight = 18 } };
        var info = Image.Identify(data, new ImageIdentifyOptions { Mode = ImageIdentifyMode.FullScan, Configuration = limits });
        Assert.Equal((20, 18), (info.Width, info.Height));
        var exception = Assert.Throws<ImageResourceLimitException>(() => Image.Load(data, new ImageDecodeOptions { Configuration = limits }));
        Assert.Equal((ImageResourceLimitKind.Width, 32L), (exception.Kind, exception.Requested));
        using var image = Image.Load(data, new ImageDecodeOptions { Configuration = new ImageConfiguration { Limits = new ImageResourceLimits { MaxWidth = 32, MaxHeight = 32, MaxFramePixels = 1024 } } });
        Assert.Equal((20, 18), (image.Width, image.Height));

        // One direction at a time: a window that removes the padding of the rows and whole blocks of columns counts the
        // coded width and the output height
        Assert.Equal((32, 18, 32L * 18), FixtureTraits.GetLimitedCanvas(GoldenCorpus.Default.Get("heic/window-beyond-padding-columns-444"), decodes: true));
        Assert.Equal((20, 18, 20L * 18), FixtureTraits.GetLimitedCanvas(GoldenCorpus.Default.Get("heic/window-beyond-padding-columns-444")));
    }

    [Fact]
    public void CleanApertureOfASampleEntryCropsTheImagesOfTheTrack()
    {
        // The pictures of the track have the size of the sample entry; its clap box selects the images in them: an odd size
        // at the top-left corner of 4:2:0 pictures, and a rectangle at an offset, in a color track and in its alpha track
        var odd = GoldenCorpus.Default.Get("heic/sequence-clap-odd-420");
        var oddTrack = ReferenceHeif.Parse(odd.ReadInput()).ColorTrack!;
        Assert.Equal((20, 18), (oddTrack.Width, oddTrack.Height));
        Assert.Equal((0, 0, 19, 17), oddTrack.CleanAperture!.GetRectangle(20, 18));
        Assert.Equal((19, 17), (odd.Expected.Width, odd.Expected.Height));

        var offset = GoldenCorpus.Default.Get("heic/sequence-clap-offset-alpha");
        var file = ReferenceHeif.Parse(offset.ReadInput());
        Assert.Equal((5, 4, 12, 10), file.ColorTrack!.CleanAperture!.GetRectangle(20, 18));
        Assert.Equal(file.ColorTrack.CleanAperture, file.AlphaTrack!.CleanAperture);
        Assert.Equal((12, 10), (offset.Expected.Width, offset.Expected.Height));

        // The same pictures without the aperture are the whole images, of which these are the rectangles
        var whole = GoldenCorpus.Default.Get("heic/sequence-window-420");
        Assert.Equal(ReferenceHeif.Parse(whole.ReadInput()).ColorTrack!.Samples.Count, oddTrack.Samples.Count);
        for (var i = 0; i < odd.Expected.FrameCount; i++)
        {
            var (cropped, full) = (odd.GetFrame(i, RawPixelLayout.Rgba8), whole.GetFrame(i, RawPixelLayout.Rgba8));
            for (var y = 0; y < cropped.Height; y++)
            {
                for (var x = 0; x < cropped.Width; x++)
                {
                    Assert.Equal((full.GetSample(x, y, 0), full.GetSample(x, y, 1), full.GetSample(x, y, 2)), (cropped.GetSample(x, y, 0), cropped.GetSample(x, y, 1), cropped.GetSample(x, y, 2)));
                }
            }
        }

        // The limits of the canvas apply to the pictures, as for the clean aperture of an image item
        Assert.Equal((20, 18, 20L * 18), FixtureTraits.GetLimitedCanvas(odd));
    }

    [Fact]
    public void ErrorFixturesAreWhatTheirNotesSay()
    {
        // The independent reader confirms the structural facts that the error fixtures are built on
        Assert.Contains(Read("invalid/heic/premultiplied-alpha").ItemReferences, reference => reference.Type == "prem");
        Assert.True(Read("invalid/heic/sequence-fragmented").IsFragmented);
        Assert.Null(Read("invalid/heic/missing-pitm").PrimaryItemId);
        Assert.Null(Read("invalid/heic/missing-ispe").PrimaryItem!.Size);
        Assert.Null(Read("invalid/heic/missing-hvcc").PrimaryItem!.HevcConfiguration);
        Assert.Equal("iden", Read("invalid/heic/derived-iden").PrimaryItem!.Type);
        Assert.Equal("iovl", Read("invalid/heic/derived-iovl").PrimaryItem!.Type);
        Assert.Equal("lhv1", Read("invalid/heic/item-lhv1").PrimaryItem!.Type);
        Assert.Equal(1, Read("invalid/heic/layer-selector").PrimaryItem!.LayerSelector);
        Assert.Null(Read("invalid/heic/clap-fractional").PrimaryItem!.CleanAperture!.GetRectangle(16, 16));
        Assert.Equal(14, Read("invalid/heic/matrix-ictcp").PrimaryItem!.Nclx!.MatrixCoefficients);
        Assert.Contains(Read("invalid/heic/essential-unknown-property").PrimaryItem!.Associations, association => association is { IsEssential: true, Property.Type: "zzzz" });
        var alpha = Read("invalid/heic/alpha-different-size");
        Assert.NotEqual(alpha.PrimaryItem!.Size, alpha.AlphaItem!.Size);
        Assert.Equal(3, Read("invalid/heic/grid-tile-count-mismatch").GetGridTiles(Read("invalid/heic/grid-tile-count-mismatch").PrimaryItem!).Count);
        var missingTile = Read("invalid/heic/grid-missing-tile");
        var tileIds = missingTile.ItemReferences.Single(reference => reference.Type == "dimg" && reference.FromItemId == missingTile.PrimaryItemId).ToItemIds;
        Assert.Contains(tileIds, id => missingTile.FindItem(id) is null);
        Assert.Contains(tileIds, id => missingTile.FindItem(id) is { Type: "hvc1" });

        // Brands and codecs: an hvc1 item under the brands of AVIF only, an av01 item under the brands of HEIC only
        var hevcUnderAvif = Read("invalid/heic/ftyp-without-heic-brand");
        Assert.True(hevcUnderAvif.HasBrand("avif") && !hevcUnderAvif.HasBrand("heic") && !hevcUnderAvif.HasBrand("heix"));
        Assert.Equal("hvc1", hevcUnderAvif.PrimaryItem!.Type);
        var av1UnderHeic = Read("invalid/heic/item-av01");
        Assert.True(av1UnderHeic.HasBrand("heic") && !av1UnderHeic.HasBrand("avif"));
        Assert.Equal("av01", av1UnderHeic.PrimaryItem!.Type);

        // Configuration records: the version, a reserved length size, a sample format that is not the one of the
        // sequence parameter set it holds. The independent reader rejects the first one and the truncated record
        Assert.Throws<InvalidDataException>(() => Read("invalid/heic/hvcc-version").PrimaryItem!.HevcConfiguration);
        Assert.Throws<InvalidDataException>(() => Read("invalid/heic/hvcc-truncated").PrimaryItem!.HevcConfiguration);
        Assert.Equal(3, Read("invalid/heic/hvcc-length-size-reserved").PrimaryItem!.HevcConfiguration!.NalUnitLengthSize);
        var source = Read("heic/nclx-overrides-bitstream").PrimaryItem!.HevcConfiguration!;
        Assert.Equal((3, 8), (source.ChromaFormat, source.BitDepthLuma));
        Assert.Equal((3, 10), (Read("invalid/heic/hvcc-bit-depth-mismatch").PrimaryItem!.HevcConfiguration!.ChromaFormat, Read("invalid/heic/hvcc-bit-depth-mismatch").PrimaryItem!.HevcConfiguration!.BitDepthLuma));
        Assert.Equal((1, 8), (Read("invalid/heic/hvcc-chroma-format-mismatch").PrimaryItem!.HevcConfiguration!.ChromaFormat, Read("invalid/heic/hvcc-chroma-format-mismatch").PrimaryItem!.HevcConfiguration!.BitDepthLuma));

        // The NAL units of an item (table 7-1 of Rec. ITU-T H.265: types below 32 are slice segments, 16 to 23 those of an
        // intra random access point picture; the first bit after the two-byte header starts a picture)
        Assert.HasCount(1, Pictures("heic/nclx-overrides-bitstream"));
        Assert.Empty(Pictures("invalid/heic/no-picture"));
        Assert.NotEmpty(Units("invalid/heic/no-picture"));
        Assert.HasCount(2, Pictures("invalid/heic/two-pictures"));
        Assert.InRange(Pictures("heic/nclx-overrides-bitstream")[0], 16, 23);
        Assert.InRange(Pictures("invalid/heic/first-picture-not-irap")[0], 0, 9);
        foreach (var id in new[] { "invalid/heic/nal-length-exceeds-item", "invalid/heic/nal-length-truncated" })
        {
            Assert.Throws<InvalidDataException>(() => Units(id));
        }

        Assert.True(Units("invalid/heic/slice-data-truncated").Sum(unit => unit.Length) < Units("heic/nclx-overrides-bitstream").Sum(unit => unit.Length));
        Assert.Equal(Units("heic/nclx-overrides-bitstream").Select(unit => unit.Length), Units("invalid/heic/cabac-garbage").Select(unit => unit.Length));

        // A grid as heif-enc writes it for small tiles: a clap property on each tile, none on the grid
        var tileClap = Read("invalid/heic/grid-tile-clap");
        Assert.Null(tileClap.PrimaryItem!.CleanAperture);
        Assert.All(tileClap.GetGridTiles(tileClap.PrimaryItem), tile => Assert.NotNull(tile.CleanAperture));

        // Image sequences: no HEVC track; two samples with one composition time; a sample entry of another size than the
        // pictures (assembled, and as heif-enc writes it for small images); a record that is not the one of the bitstream
        Assert.All(Read("invalid/heic/sequence-no-hevc-track").Tracks, track => Assert.Equal("avc1", track.SampleEntryType));
        var collision = Read("invalid/heic/sequence-ctts-collision").Tracks[0];
        Assert.Equal(collision.Samples[0].Duration + collision.CompositionOffsets![1], collision.CompositionOffsets[0]);
        var valid = Read("heic/sequence-window-reordered-2-plays").ColorTrack!;
        Assert.Equal((20, 18), (valid.Width, valid.Height));
        Assert.Equal((24, 24), (Read("invalid/heic/sequence-size-mismatch").ColorTrack!.Width, Read("invalid/heic/sequence-size-mismatch").ColorTrack!.Height));
        Assert.Equal((16, 12), (Read("invalid/heic/sequence-padded-pictures").ColorTrack!.Width, Read("invalid/heic/sequence-padded-pictures").ColorTrack!.Height));
        Assert.Null(Read("invalid/heic/sequence-padded-pictures").ColorTrack!.CleanAperture); // no clap box selects the images in the 64x64 pictures
        Assert.Equal(valid.Samples.Count - 1, Read("invalid/heic/sequence-missing-reference").ColorTrack!.Samples.Count);
        Assert.Equal(10, Read("invalid/heic/sequence-record-mismatch").ColorTrack!.HevcConfiguration!.BitDepthLuma);
        Assert.Equal(valid.EditList!.Entries[0].MediaTime + 1, Read("invalid/heic/sequence-edit-list-offset").ColorTrack!.EditList!.Entries[0].MediaTime);
        Assert.NotEqual(0, valid.EditList.Entries[0].MediaTime);

        // The files the independent reader rejects too
        foreach (var id in new[] { "invalid/heic/truncated-meta", "invalid/heic/child-box-exceeds-parent", "invalid/heic/sequence-track-meta-malformed" })
        {
            Assert.Throws<InvalidDataException>(() => Read(id));
        }

        static ReferenceHeif Read(string id) => ReferenceHeif.Parse(GoldenCorpus.Default.Get(id).ReadInput());

        static IReadOnlyList<ReadOnlyMemory<byte>> Units(string id)
        {
            var file = Read(id);
            return file.PrimaryItem!.HevcConfiguration!.SplitNalUnits(file.ReadItemData(file.PrimaryItem));
        }

        // The type of the first slice segment of each picture of the primary item
        static List<int> Pictures(string id) => [.. Units(id).Where(unit => ((unit.Span[0] >> 1) & 0x3F) < 32 && (unit.Span[2] & 0x80) != 0).Select(unit => (unit.Span[0] >> 1) & 0x3F)];
    }

    private static (int Max, double Mean, string Location) Measure(RawPixelBuffer expected, RawPixelBuffer actual)
    {
        Assert.Equal(expected.Layout, actual.Layout);
        Assert.Equal((expected.Width, expected.Height), (actual.Width, actual.Height));
        var channels = expected.Layout.ChannelCount;
        var max = 0;
        var sum = 0L;
        var count = 0;
        var location = "(none)";
        for (var y = 0; y < expected.Height; y++)
        {
            for (var x = 0; x < expected.Width; x++)
            {
                for (var c = 0; c < channels; c++)
                {
                    var difference = Math.Abs(expected.GetSample(x, y, c) - actual.GetSample(x, y, c));
                    if (c == 3)
                    {
                        Assert.Equal(0, difference); // alpha is exact
                        continue;
                    }

                    sum += difference;
                    count++;
                    if (difference > max)
                    {
                        max = difference;
                        location = string.Create(CultureInfo.InvariantCulture, $"({x}, {y}) channel {c}");
                    }
                }
            }
        }

        return (max, (double)sum / count, location);
    }
}
